import re

REGLAMENT = 'ред. 1 от 27.10.2026'


def P(*abzacy):
    return ''.join('<p>' + a + '</p>' for a in abzacy)


def UL(*punkty):
    return '<ul>' + ''.join('<li>' + p + '</li>' for p in punkty) + '</ul>'


def OL(*punkty):
    return '<ol>' + ''.join('<li>' + p + '</li>' for p in punkty) + '</ol>'


def H(t):
    return '<h3>' + t + '</h3>'


def TAB(shapka, stroki):
    h = ''.join('<th>' + x + '</th>' for x in shapka)
    r = ''.join('<tr>' + ''.join('<td>' + x + '</td>' for x in s) + '</tr>' for s in stroki)
    return '<div class="scroller"><table><thead><tr>' + h + '</tr></thead><tbody>' + r + '</tbody></table></div>'


def KEIS(situaciya, razbor):
    return ('<div class="keis"><span class="tag">Кейс</span><p>' + situaciya + '</p>'
            '<details><summary>Разбор</summary><p>' + razbor + '</p></details></div>')


def NELZYA(t):
    return '<div class="pitfall"><span class="tag">Так делать нельзя</span><p>' + t + '</p></div>'


def VAZHNO(t):
    return '<div class="robot"><span class="tag">Главное</span><p>' + t + '</p></div>'


def SKAZAT(t):
    """Готовая фраза для клиента."""
    return '<div class="primer"><span class="tag">Что сказать</span><p>' + t + '</p></div>'


# Программа целиком отдельной страницей и PDF для печати (platforma/dokumenty, курс лежит в platforma/kurs).
STRANICA = '../dokumenty/zhaloby.html'
PDF = [('программа коротко', 'zhaloby-programma-korotko.pdf'), ('регламент', 'zhaloby-reglament.pdf'),
       ('памятка', 'zhaloby-pamyatka.pdf'), ('карточки', 'zhaloby-kartochki.pdf'), ('алгоритм', 'zhaloby-algoritm.pdf')]


def SSYLKA(href, tekst):
    return '<a href="' + href + '" target="_blank" rel="noopener">' + tekst + '</a>'


PROGRAMMA = ('<div class="primer"><span class="tag">Программа целиком - просто почитать</span>'
             '<p><strong>' + SSYLKA(STRANICA, 'Открыть программу «Клиент на всю жизнь» целиком') + '</strong> - коротко о программе, '
             'алгоритм фиксации, регламент, памятка и карточки ситуаций на одной странице.</p>'
             '<p>PDF для печати: ' + ', '.join(SSYLKA('../dokumenty/' + f, n) for n, f in PDF) + '.</p></div>')


def DOC(nazv, bloki):
    """Блок «Читать инструкцию целиком»: полный текст документа под раскрывашкой (как в курсе instrukcii-seller)."""
    h = ''
    for vid, x in bloki:
        if vid == 'p':
            h += '<p>' + x + '</p>'
        elif vid == 'b':
            h += '<p><strong>' + x + '</strong></p>'
        else:
            h += TAB(x[0], x[1:])
    return ('<details class="verify" style="margin-top:26px"><summary>Читать инструкцию целиком - ' + nazv + '</summary>'
            '<p style="margin:10px 0 0">' + SSYLKA(STRANICA, 'Открыть отдельной страницей') + '</p>'
            '<div class="docfull" style="max-height:420px;overflow-y:auto;padding:0 8px 0 14px;'
            'border-left:2px solid var(--line);font-size:14px;line-height:1.5">' + h + '</div></details>')


def FR(*ids):
    """Таблица фраз ru/kk из FRAZY (казахский - дословно из json)."""
    return TAB(['По-русски', 'По-казахски'], [[FRAZY[i][0], '<span class="hangyl">' + FRAZY[i][1] + '</span>'] for i in ids])


