# Знаки % и ₸ не отрывать от числа, а «3 000» - не рвать на телефоне: неразрывные пробелы (как % в курсе «Ручные скидки»).
def _nbsp(x):
    if isinstance(x, str):
        return re.sub(r'(\d) (\d{3})\b', '\\1\u00a0\\2', x).replace(' %', '\u00a0%').replace(' ₸', '\u00a0₸')
    if isinstance(x, list):
        return [_nbsp(i) for i in x]
    if isinstance(x, dict):
        return {k: _nbsp(v) for k, v in x.items()}
    return x


SHAGI = _nbsp(SHAGI)
BANK = _nbsp(BANK)


